Record rindex := RI { ri_vars : list (list kentry); ri_other : list kentry }.
Definition ri_bucket : ltac2:(zQ "50!hmf!tc!u2!hqf!hr8>2ri$4>1k@1$2$1@1$0$3") := ltac2:(zQ "80!tc!u2!hqf!hmf!hn6!hs2!hse!hr8\2ri$7\1k@1$1$0M1\1k@1$1$0@1$3$2^1\1n$0@3$4$2@1$6^3^1@1$5^2").
Fixpoint mk_ri (fk : list kentry) : rindex :=
  match fk with
  | [] => RI [] []
  | K :: rest =>
      let t := mk_ri rest in
      match K with
      | KRange e' _ _ =>
          match vkey_of e' with
          | Some n => RI (lset (ri_vars t) n K) (ri_other t)
          | None => RI (ri_vars t) (K :: ri_other t)
          end
      | _ => t
      end
  end.
